<div class="cabine-color-picker" data-cabine-colors>
 <div class="cabine-color-picker-title"><div class="cabine-color-heading"><span>Personalize seu gabinete</span><strong>Monte sua combina&ccedil;&atilde;o</strong></div><div class="cabine-color-actions"><button type="button" data-cabine-random>Surpreenda-me</button><button type="button" data-cabine-reset>Restaurar</button></div></div>
 <div class="cabine-color-row">
  <span class="cabine-color-label">Painel <strong data-cabine-panel-name>Laranja</strong></span>
  <div class="cabine-color-options" role="group" aria-label="Escolha a cor do painel">
   <button class="is-active" type="button" data-cabine-panel="orange" data-color-name="Laranja" aria-label="Painel laranja" aria-pressed="true"><span class="swatch-orange" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="red" data-color-name="Vermelho" aria-label="Painel vermelho" aria-pressed="false"><span class="swatch-red" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="yellow" data-color-name="Amarelo" aria-label="Painel amarelo" aria-pressed="false"><span class="swatch-yellow" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="green" data-color-name="Verde" aria-label="Painel verde" aria-pressed="false"><span class="swatch-green" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="blue" data-color-name="Azul" aria-label="Painel azul" aria-pressed="false"><span class="swatch-blue" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="cyan" data-color-name="Ciano" aria-label="Painel ciano" aria-pressed="false"><span class="swatch-cyan" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="purple" data-color-name="Roxo" aria-label="Painel roxo" aria-pressed="false"><span class="swatch-purple" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="white" data-color-name="Branco" aria-label="Painel branco" aria-pressed="false"><span class="swatch-white" aria-hidden="true"></span></button>
   <button type="button" data-cabine-panel="black" data-color-name="Preto" aria-label="Painel preto" aria-pressed="false"><span class="swatch-black" aria-hidden="true"></span></button>
   <label class="cabine-custom-color-field"><span>Cor livre</span><input class="cabine-custom-color" type="color" value="#e85b1b" data-cabine-panel-custom aria-label="Escolher uma cor personalizada para o painel" title="Escolher outra cor para o painel"></label>
  </div>
 </div>
 <div class="cabine-color-row">
  <span class="cabine-color-label">Estrutura <strong data-cabine-frame-name>Cinza</strong></span>
  <div class="cabine-color-options" role="group" aria-label="Escolha a cor da estrutura">
   <button class="is-active" type="button" data-cabine-frame="gray" data-color-name="Cinza" aria-label="Estrutura cinza" aria-pressed="true"><span class="swatch-gray" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="white" data-color-name="Branca" aria-label="Estrutura branca" aria-pressed="false"><span class="swatch-white" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="graphite" data-color-name="Grafite" aria-label="Estrutura grafite" aria-pressed="false"><span class="swatch-graphite" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="navy" data-color-name="Azul" aria-label="Estrutura azul" aria-pressed="false"><span class="swatch-navy" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="black" data-color-name="Preta" aria-label="Estrutura preta" aria-pressed="false"><span class="swatch-black" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="red" data-color-name="Vermelha" aria-label="Estrutura vermelha" aria-pressed="false"><span class="swatch-red" aria-hidden="true"></span></button>
   <button type="button" data-cabine-frame="beige" data-color-name="Bege" aria-label="Estrutura bege" aria-pressed="false"><span class="swatch-beige" aria-hidden="true"></span></button>
   <label class="cabine-custom-color-field"><span>Cor livre</span><input class="cabine-custom-color" type="color" value="#aeb3b7" data-cabine-frame-custom aria-label="Escolher uma cor personalizada para a estrutura" title="Escolher outra cor para a estrutura"></label>
  </div>
 </div>
</div>
